import {api} from '../api.js';
import {state} from '../state.js';
import {enhanceThemeForClientAdmin} from './theme_manager.js';
import {$, $$, esc, modal, money, number, pageHead, toast} from '../ui.js';

const supported = new Set(['campaigns','email','forecast','reports','training','organization','solutions']);
const f = (label,name,type='text',value='',extra='') => `<div class="field"><label>${esc(label)}</label><input name="${esc(name)}" type="${type}" value="${esc(value??'')}" ${extra}></div>`;
const ta = (label,name,value='',extra='') => `<div class="field full"><label>${esc(label)}</label><textarea name="${esc(name)}" ${extra}>${esc(value??'')}</textarea></div>`;
const sel = (label,name,options,value='') => `<div class="field"><label>${esc(label)}</label><select name="${esc(name)}">${options.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('')}</select></div>`;
const dt = value => value ? new Date(value).toLocaleString() : '—';
const currency = cents => money(Number(cents||0));
const roleLabel = role => ({CLIENT_ADMIN:'Client Administrator',VP_SALES:'VP of Sales',SALES_MANAGER:'Sales Manager',SALES_REP:'Sales Representative',MARKETING_USER:'Marketing User',EXECUTIVE_VIEWER:'Executive Viewer'})[role]||role||'—';

export function clientAdminCorrectionApplies(route){
  return state.user?.tenant_role === 'CLIENT_ADMIN' && supported.has(route);
}

export async function renderClientAdminCorrection(route, page, ctx){
  if(!clientAdminCorrectionApplies(route)) return false;
  if(route==='campaigns') await campaigns(page,ctx);
  else if(route==='email') await emailWorkspace(page,ctx);
  else if(route==='forecast') await forecast(page,ctx);
  else if(route==='reports') await reports(page,ctx);
  else if(route==='training') await training(page,ctx);
  else if(route==='organization') { await organization(page,ctx); await enhanceThemeForClientAdmin(page,ctx); }
  else if(route==='solutions') await solutions(page,ctx);
  return true;
}

export async function enhanceWebsiteForClientAdmin(page){
  if(state.user?.tenant_role!=='CLIENT_ADMIN') return;
  try{
    const config=await api(`/api/v521/tenants/${state.selectedTenantId}/website-connection`);
    const panel=document.createElement('section');panel.className='ca-section';panel.id='ca-website-strategy';
    panel.innerHTML=`<div class="ca-section-head"><div><h2>Website strategy</h2><p>Connect an existing/custom website or preserve the RMR managed-site option.</p></div></div>
    <div class="ca-notice"><div><strong>Recommended commercial model</strong><small>Use an external/custom website for most clients. RMR Global remains the operating system for PIQ, CRM, campaigns, reporting and training. The managed website builder remains available for selected packages.</small></div></div>
    <form id="ca-website-form" class="ca-form ca-grid-2">
      ${sel('Website mode','mode',[['external','External / Custom Website'],['managed','RMR Managed Website']],config.mode)}
      ${f('External website URL','external_url','url',config.external_url||'','placeholder="https://example.com"')}
      <div class="full ca-toolbar"><button class="button" type="submit">Save Website Strategy</button><button class="button secondary" type="button" id="ca-test-website">Save & Test</button><a class="button secondary" id="ca-open-website" href="${esc(config.mode==='external'?(config.external_url||'#'):config.managed_url)}" target="_blank" rel="noopener">Open Website</a></div>
    </form>`;
    const head=page.querySelector('.page-head');head?.insertAdjacentElement('afterend',panel);
    const form=$('#ca-website-form',panel);
    const toggle=()=>{form.external_url.disabled=form.mode.value!=='external'};toggle();form.mode.addEventListener('change',toggle);
    const save=async(test=false)=>{try{const body={mode:form.mode.value,external_url:form.external_url.value};const saved=await api(`/api/v521/tenants/${state.selectedTenantId}/website-connection`,{method:'PATCH',body});if(test){const result=await api(`/api/v521/tenants/${state.selectedTenantId}/website-connection/test`,{method:'POST',body});toast(result.detail)}else toast('Website strategy saved');$('#ca-open-website',panel).href=saved.mode==='external'?saved.external_url:saved.managed_url}catch(e){toast(e.message,'error')}};
    form.addEventListener('submit',e=>{e.preventDefault();save(false)});$('#ca-test-website',panel).addEventListener('click',()=>save(true));
  }catch(e){console.warn('Website strategy enhancement unavailable',e)}
}

async function campaigns(page,ctx){
  const env=await api(`/api/v521/tenants/${state.selectedTenantId}/environment`);
  const [social,exports]=await Promise.all([api(`/api/v521/tenants/${state.selectedTenantId}/social`),api(`/api/v521/tenants/${state.selectedTenantId}/campaign-exports`)]);
  const tab=state.unifiedTab.caCampaigns||'social';
  page.innerHTML=`${pageHead('Campaigns & Social','Use AI to create finished platform-specific social content, then build segmented bulk-email export packages for a dedicated email platform.',`<button class="button" id="ca-generate-social">Generate Social Content</button><button class="button secondary" id="ca-create-export">Create Email Campaign Export</button>`)}
  <div class="ca-notice ${env.demo_mode?'warn':''}"><div><strong>${env.demo_mode?'Product Owner demonstration generator':'Production AI content generation'}</strong><small>RMR Global contains the AI-provider integration. Production deployment supplies the approved provider/model credentials. The user provides intent; the application writes finished copy, hooks, calls to action, hashtags, keywords and visual guidance.</small></div></div>
  <div class="ca-tabbar"><button data-ca-campaign-tab="social" class="${tab==='social'?'active':''}">Social Content</button><button data-ca-campaign-tab="exports" class="${tab==='exports'?'active':''}">Email Campaign Exports</button><button data-ca-campaign-tab="calendar" class="${tab==='calendar'?'active':''}">Content Calendar</button></div>
  <div id="ca-campaign-content">${tab==='social'?socialCards(social.items):tab==='exports'?exportTable(exports.items):contentCalendar(social.items,exports.items)}</div>`;
  $$('[data-ca-campaign-tab]').forEach(btn=>btn.addEventListener('click',()=>{state.unifiedTab.caCampaigns=btn.dataset.caCampaignTab;ctx.navigate('campaigns')}));
  $('#ca-generate-social').addEventListener('click',()=>socialModal(ctx));
  $('#ca-create-export').addEventListener('click',()=>campaignExportModal(ctx));
  bindSocialActions(ctx);
}
function socialCards(items){return `<div class="ca-grid-2">${items.length?items.map(item=>`<article class="ca-social-card"><div class="ca-status-row"><span class="ca-pill">${esc(item.platform)}</span><span class="ca-pill ${item.status==='PUBLISHED'?'green':'amber'}">${esc(item.status)}</span>${item.generation?.provider?`<span class="ca-pill">${esc(item.generation.provider)}</span>`:''}</div><strong>${esc(item.title||'Social draft')}</strong><div class="social-preview-card"><div class="post-body">${esc(item.post_text)}</div><div class="hashtags" data-social-tags="${item.id}">${esc(item.hashtags||'')}</div></div>${item.generation?`<div class="ca-meta-list"><span><b>Hook:</b> ${esc(item.generation.hook||'—')}</span><span><b>CTA:</b> ${esc(item.generation.call_to_action||item.generation.cta||'—')}</span><span><b>Keywords:</b> ${esc((item.generation.keywords_json||item.generation.keywords||[]).join(', '))}</span><span><b>Suggested visual:</b> ${esc(item.generation.suggested_visual||'—')}</span></div>`:''}<textarea class="ca-hidden" data-social-text="${item.id}">${esc(item.post_text)}</textarea><div class="ca-toolbar"><button class="button small" data-open-social="${item.id}">Open / Edit</button><button class="button secondary small" data-regenerate-social="${item.id}">Regenerate</button><button class="button secondary small" data-copy-social="${item.id}">Copy Post</button><button class="button secondary small" data-copy-tags="${item.id}">Copy Hashtags</button></div></article>`).join(''):'<div class="ca-empty">No social drafts yet. Generate content from a business objective.</div>'}</div>`}
function exportTable(items){return `<section class="ca-section"><div class="ca-section-head"><div><h2>Email Campaign Export Packages</h2><p>RMR Global creates and segments the campaign. Mailchimp, Constant Contact, HubSpot, Brevo or another dedicated platform handles bulk delivery.</p></div></div>${items.length?`<div class="ca-table-wrap"><table class="ca-table"><thead><tr><th>Package</th><th>Format</th><th>Recipients</th><th>Subject</th><th>Created</th><th></th></tr></thead><tbody>${items.map(x=>`<tr><td><strong>${esc(x.name)}</strong></td><td>${esc(x.provider_format)}</td><td>${number(x.record_count)}</td><td>${esc(x.subject||'—')}</td><td>${dt(x.created_at)}</td><td><a class="button secondary small" href="/api/v521/campaign-exports/${x.id}/download">Export CSV</a></td></tr>`).join('')}</tbody></table></div>`:'<div class="ca-empty">No campaign export packages yet.</div>'}</section>`}
function contentCalendar(social,exports){const rows=[...social.map(x=>({date:x.created_at,label:x.title,type:x.platform,status:x.status})),...exports.map(x=>({date:x.created_at,label:x.name,type:'Email Export',status:'READY'}))].sort((a,b)=>new Date(b.date)-new Date(a.date));return `<section class="ca-section"><div class="ca-list">${rows.map(x=>`<div class="ca-list-row"><div><strong>${esc(x.label)}</strong><small>${new Date(x.date).toLocaleDateString()} · ${esc(x.type)}</small></div><span class="ca-pill">${esc(x.status)}</span></div>`).join('')||'<div class="ca-empty">No content scheduled or created.</div>'}</div></section>`}
function socialModal(ctx){modal({title:'Generate finished social content',wide:true,body:`<div class="ca-dialog-note">Give RMR Global the campaign intent. The application writes the finished platform-specific content; you review and edit before publishing.</div><form id="ca-social-form" class="ca-form ca-modal-grid">${ta('Objective / message','objective','','placeholder="Promote relocation buyers moving from Arizona to Northern Colorado." required')}${f('Target audience','audience','text','','placeholder="Arizona homeowners considering a move" required')}${f('Tone','tone','text','friendly, professional and locally knowledgeable')}${f('Call to action','call_to_action','text','Schedule a consultation')}${f('Keywords (comma separated)','keywords','text','relocation, Northern Colorado, home buyer')}${ta('Suggested visual context (optional)','suggested_visual','','placeholder="A family arriving at a Northern Colorado home"')}</form>`,footer:'<button class="button secondary" data-close-modal>Cancel</button><button class="button" id="ca-run-social">Generate Four Posts</button>',onOpen:(root,close)=>$('#ca-run-social',root).addEventListener('click',async()=>{const form=$('#ca-social-form',root);if(!form.reportValidity())return;try{const result=await api(`/api/v521/tenants/${state.selectedTenantId}/social/generate`,{method:'POST',body:{objective:form.objective.value,audience:form.audience.value,tone:form.tone.value,call_to_action:form.call_to_action.value,keywords:form.keywords.value.split(',').map(x=>x.trim()).filter(Boolean),suggested_visual:form.suggested_visual.value}});toast(result.demonstration?'Demonstration AI content generated':'AI content generated');close();ctx.navigate('campaigns')}catch(e){toast(e.message,'error')}})});}
function campaignExportModal(ctx){modal({title:'Create segmented email-platform export',wide:true,body:`<div class="ca-notice"><div><strong>No bulk delivery from RMR Global</strong><small>Create the campaign content and audience here, then export a provider-ready CSV to a compliant bulk-email platform.</small></div></div><form id="ca-export-form" class="ca-form ca-modal-grid">${f('Package name','name','text','Qualified Prospect Follow-Up','required')}${sel('Export format','provider_format',[['mailchimp','Mailchimp'],['constant_contact','Constant Contact'],['hubspot','HubSpot'],['brevo','Brevo'],['generic','Generic CSV']],'mailchimp')}<div class="field full"><label>Audience sources</label><label><input type="checkbox" name="include_leads" checked> CRM Leads</label> <label><input type="checkbox" name="include_contacts" checked> CRM Contacts</label> <label><input type="checkbox" name="include_piq"> Enriched PIQ records with email</label></div>${f('Lead statuses (comma separated)','lead_statuses','text','New, Contacted, Qualified')}${f('Sources (optional)','sources','text','ProspectIQ, Website, Referral')}${f('Subject line','subject','text','A quick idea for your next move')}${f('Preview text','preview_text','text','Practical guidance tailored to your goals')}${ta('Finished email content','email_body','Hello {{First Name}},\n\nWe prepared a brief resource that may help with your next step.\n\nBest,\nKerry')}${f('Call to action','call_to_action','text','Schedule a consultation')}</form>`,footer:'<button class="button secondary" data-close-modal>Cancel</button><button class="button" id="ca-save-export">Create Export Package</button>',onOpen:(root,close)=>$('#ca-save-export',root).addEventListener('click',async()=>{const form=$('#ca-export-form',root);if(!form.reportValidity())return;try{await api(`/api/v521/tenants/${state.selectedTenantId}/campaign-exports`,{method:'POST',body:{name:form.name.value,provider_format:form.provider_format.value,include_leads:form.include_leads.checked,include_contacts:form.include_contacts.checked,include_piq:form.include_piq.checked,lead_statuses:form.lead_statuses.value.split(',').map(x=>x.trim()).filter(Boolean),sources:form.sources.value.split(',').map(x=>x.trim()).filter(Boolean),subject:form.subject.value,preview_text:form.preview_text.value,email_body:form.email_body.value,call_to_action:form.call_to_action.value}});toast('Campaign export package created');close();state.unifiedTab.caCampaigns='exports';ctx.navigate('campaigns')}catch(e){toast(e.message,'error')}})});}
function bindSocialActions(ctx){
  $$('[data-copy-social]').forEach(btn=>btn.addEventListener('click',async()=>{await navigator.clipboard.writeText($(`[data-social-text="${btn.dataset.copySocial}"]`).value);toast('Post copied')}));
  $$('[data-copy-tags]').forEach(btn=>btn.addEventListener('click',async()=>{await navigator.clipboard.writeText($(`[data-social-tags="${btn.dataset.copyTags}"]`).textContent);toast('Hashtags copied')}));
  $$('[data-open-social]').forEach(btn=>btn.addEventListener('click',()=>socialEditorModal(btn.dataset.openSocial,ctx)));
  $$('[data-regenerate-social]').forEach(btn=>btn.addEventListener('click',async()=>{try{await api(`/api/v522/tenants/${state.selectedTenantId}/social/${btn.dataset.regenerateSocial}/regenerate`,{method:'POST',body:{}});toast('Platform-specific draft regenerated');ctx.navigate('campaigns')}catch(e){toast(e.message,'error')}}));
}
async function socialEditorModal(id,ctx){try{const data=await api(`/api/v522/tenants/${state.selectedTenantId}/social/${id}`);const item=data.item,g=data.generation;modal({title:`${esc(item.platform)} social content`,wide:true,body:`<div class="ca-notice ${g?.provider==='demonstration'?'warn':''}"><div><strong>${g?.provider==='demonstration'?'Demonstration content — no external AI call':'AI-assisted content record'}</strong><small>${g?`Objective: ${esc(g.objective||'—')} · Audience: ${esc(g.audience||'—')}`:'This record predates generation metadata.'}</small></div></div><form id="v522-social-edit" class="ca-form">${f('Title / hook','title','text',item.title||'','required')}${ta('Finished post','post_text',item.post_text||'','required')}${ta('Hashtags','hashtags',item.hashtags||'')}${sel('Status','status',[['DRAFT','Draft'],['APPROVED','Approved'],['PUBLISHED','Published'],['ARCHIVED','Archived']],item.status)}</form>${g?`<div class="ca-meta-list"><span><b>CTA:</b> ${esc(g.call_to_action||'—')}</span><span><b>Keywords:</b> ${esc((g.keywords_json||[]).join(', '))}</span><span><b>Suggested visual:</b> ${esc(g.suggested_visual||'—')}</span></div>`:''}${data.revisions.length?`<p class="muted">${data.revisions.length} prior revision(s) retained.</p>`:''}`,footer:'<button class="button secondary" data-close-modal>Cancel</button><button class="button secondary" id="v522-regenerate-open">Regenerate</button><button class="button" id="v522-save-social">Save</button>',onOpen:(root,close)=>{$('#v522-save-social',root).addEventListener('click',async()=>{const form=$('#v522-social-edit',root);if(!form.reportValidity())return;try{await api(`/api/v522/tenants/${state.selectedTenantId}/social/${id}`,{method:'PATCH',body:{title:form.title.value,post_text:form.post_text.value,hashtags:form.hashtags.value,status:form.status.value}});toast('Social content saved');close();ctx.navigate('campaigns')}catch(e){toast(e.message,'error')}});$('#v522-regenerate-open',root).addEventListener('click',async()=>{try{await api(`/api/v522/tenants/${state.selectedTenantId}/social/${id}/regenerate`,{method:'POST',body:{}});toast('Draft regenerated');close();ctx.navigate('campaigns')}catch(e){toast(e.message,'error')}})}})}catch(e){toast(e.message,'error')}}

async function emailWorkspace(page,ctx){
  const data=await api(`/api/v521/tenants/${state.selectedTenantId}/email-workspace`);const tab=state.unifiedTab.caEmail||'overview';
  page.innerHTML=`${pageHead('Email & Activities','Send one-to-one messages from the client’s connected mailbox and retain CRM-relevant communication history.',`<button class="button" id="ca-new-email">+ New One-to-One Email</button><button class="button secondary" id="ca-manage-email">Manage Connections</button>`)}<div class="ca-notice"><div><strong>Client-owned sending</strong><small>Individual email is sent through the client’s connected mailbox and recorded against CRM relationships. Bulk campaigns are exported to a dedicated email platform; RMR Global does not operate a mass-email delivery system.</small></div></div>
  <div class="ca-action-grid"><button class="ca-action-card" data-email-tab="connections"><span>Connections</span><strong>${number(data.connections.length)}</strong><span>Open connection management</span></button><button class="ca-action-card" data-email-tab="messages"><span>Recorded Messages</span><strong>${number(data.messages.length)}</strong><span>Open one-to-one email history</span></button><button class="ca-action-card" data-email-tab="timeline"><span>Timeline Events</span><strong>${number(data.activities.length)}</strong><span>Open CRM activity history</span></button><button class="ca-action-card" id="ca-open-crm"><span>CRM</span><strong>Open</strong><span>Accounts, leads and opportunities</span></button></div>
  <div class="ca-tabbar" style="margin-top:14px"><button data-email-tab="overview" class="${tab==='overview'?'active':''}">Overview</button><button data-email-tab="connections" class="${tab==='connections'?'active':''}">Connections</button><button data-email-tab="messages" class="${tab==='messages'?'active':''}">Messages</button><button data-email-tab="timeline" class="${tab==='timeline'?'active':''}">Timeline</button></div><div id="ca-email-detail">${emailDetail(tab,data)}</div>`;
  $$('[data-email-tab]').forEach(btn=>btn.addEventListener('click',()=>{state.unifiedTab.caEmail=btn.dataset.emailTab;ctx.navigate('email')}));$('#ca-open-crm').addEventListener('click',()=>ctx.navigate('crm'));$('#ca-new-email').addEventListener('click',()=>emailModal(data,ctx));$('#ca-manage-email').addEventListener('click',()=>connectionModal(data,ctx));bindEmailActions(ctx);
}
function emailDetail(tab,data){if(tab==='connections')return `<section class="ca-section"><div class="ca-section-head"><div><h2>Connected mailboxes</h2><p>Test, synchronize or disconnect the client-owned sender.</p></div></div><div class="ca-list">${data.connections.map(c=>`<div class="ca-provider-row"><div><strong>${esc(c.sender_name||c.sender_email)}</strong><small>${esc(c.provider)} · ${esc(c.sender_email)} · ${esc(c.status)}</small></div><div class="ca-toolbar"><button class="button secondary small" data-connection-action="test" data-connection-id="${c.id}">Test</button><button class="button secondary small" data-connection-action="sync" data-connection-id="${c.id}">Sync</button><button class="button secondary small" data-connection-action="disconnect" data-connection-id="${c.id}">Disconnect</button></div></div>`).join('')||'<div class="ca-empty">No client mailbox connected.</div>'}</div></section>`;if(tab==='messages')return `<section class="ca-section"><div class="ca-section-head"><div><h2>Recorded one-to-one messages</h2><p>Open a record to see exactly what was sent, from which mailbox, by whom, and which CRM relationship it belongs to.</p></div></div><div class="ca-list">${data.messages.map(m=>`<button class="ca-list-row ca-click-row" data-message-detail="${m.id}"><div><strong>${esc(m.subject)}</strong><small>From ${esc(m.sender_email||'unknown sender')} to ${esc(m.recipient_email)} · ${esc(m.delivery_status||m.status)} · ${dt(m.sent_at||m.created_at)}</small><p>${esc(String(m.body||'').slice(0,220))}</p></div><span>Open →</span></button>`).join('')||'<div class="ca-empty">No one-to-one messages recorded.</div>'}</div></section>`;if(tab==='timeline')return `<section class="ca-section"><div class="ca-list">${data.activities.map(a=>`<div class="ca-list-row"><div><strong>${esc(a.subject||a.activity_type)}</strong><small>${esc(a.activity_type)} · ${dt(a.created_at)}</small><p>${esc(String(a.body||'').slice(0,250))}</p></div></div>`).join('')||'<div class="ca-empty">No CRM activity yet.</div>'}</div></section>`;return `<div class="ca-grid-2"><section class="ca-section"><h2>Connected senders</h2>${data.connections.map(c=>`<div class="ca-provider-row"><div><strong>${esc(c.sender_name||c.sender_email)}</strong><small>${esc(c.provider)} · ${esc(c.status)}</small></div></div>`).join('')||'<div class="ca-empty">Connect a mailbox to send one-to-one messages.</div>'}</section><section class="ca-section"><h2>Unified activity timeline</h2><div class="ca-list">${data.activities.slice(0,8).map(a=>`<div class="ca-list-row"><div><strong>${esc(a.subject||a.activity_type)}</strong><small>${dt(a.created_at)}</small></div></div>`).join('')||'<div class="ca-empty">No activity yet.</div>'}</div></section></div>`}
async function crmChoices(){const [accounts,leads,contacts,opps]=await Promise.all([api(`/api/tenants/${state.selectedTenantId}/accounts`),api(`/api/tenants/${state.selectedTenantId}/leads`),api(`/api/tenants/${state.selectedTenantId}/contacts`),api(`/api/tenants/${state.selectedTenantId}/opportunities`)]);return {accounts:accounts.accounts,leads:leads.leads,contacts:contacts.contacts,opps:opps.opportunities}}
async function emailModal(data,ctx){const crm=await crmChoices();modal({title:'Send one-to-one CRM email',wide:true,body:`<div class="ca-dialog-note">This sends through the selected client mailbox and stores the communication as CRM activity. It is not a bulk campaign.</div><form id="ca-email-form" class="ca-form ca-modal-grid">${sel('Connected mailbox','connection_id',data.connections.map(c=>[c.id,`${c.sender_email} — ${c.provider} (${c.status})`]))}${sel('CRM relationship','relationship',[['','No association'],...crm.leads.map(x=>[`lead:${x.id}`,`Lead — ${x.company_name||x.contact_name}`]),...crm.contacts.map(x=>[`contact:${x.id}`,`Contact — ${x.first_name} ${x.last_name}`]),...crm.accounts.map(x=>[`account:${x.id}`,`Account — ${x.name}`]),...crm.opps.map(x=>[`opportunity:${x.id}`,`Opportunity — ${x.name}`])])}${f('Recipient email','recipient_email','email','','required')}${f('Recipient name','recipient_name')}${f('Subject','subject','text','','required')}${ta('Message','body','','required')}</form>`,footer:'<button class="button secondary" data-close-modal>Cancel</button><button class="button" id="ca-send-email">Send & Record</button>',onOpen:(root,close)=>{$('#ca-email-form',root).relationship.addEventListener('change',e=>{const [type,id]=e.target.value.split(':');const row=type==='lead'?crm.leads.find(x=>x.id===id):type==='contact'?crm.contacts.find(x=>x.id===id):null;if(row){root.querySelector('[name=recipient_email]').value=row.email||'';root.querySelector('[name=recipient_name]').value=type==='lead'?row.contact_name:`${row.first_name} ${row.last_name}`}});$('#ca-send-email',root).addEventListener('click',async()=>{const form=$('#ca-email-form',root);if(!form.reportValidity())return;const [type,id]=(form.relationship.value||':').split(':');const body={connection_id:form.connection_id.value,recipient_email:form.recipient_email.value,recipient_name:form.recipient_name.value,subject:form.subject.value,body:form.body.value,account_id:type==='account'?id:null,opportunity_id:type==='opportunity'?id:null,lead_id:type==='lead'?id:null,contact_id:type==='contact'?id:null};try{const result=await api(`/api/v521/tenants/${state.selectedTenantId}/one-to-one-email`,{method:'POST',body});toast(result.delivery_status==='SENT'?'Email sent and recorded':'Demonstration email recorded');close();ctx.navigate('email')}catch(e){toast(e.message,'error')}})}});}
function connectionModal(data,ctx){modal({title:'Manage client mailbox connections',wide:true,body:`<div class="ca-notice"><div><strong>Client mailbox ownership</strong><small>Each client connects its own Microsoft 365, Google Workspace or SMTP mailbox. RMR Global stores tenant-isolated connection references and does not use an RMR shared sender for client communications.</small></div></div><div class="ca-list">${data.connections.map(c=>`<div class="ca-provider-row"><div><strong>${esc(c.sender_email)}</strong><small>${esc(c.provider)} · ${esc(c.status)}</small></div></div>`).join('')}</div><hr><form id="ca-connect-form" class="ca-form ca-modal-grid">${sel('Provider','provider',[['MOCK','Product Owner Demo'],['MICROSOFT','Microsoft 365'],['GOOGLE','Google Workspace'],['SMTP_IMAP','SMTP / IMAP']],'MOCK')}${f('Sender email','sender_email','email','','required')}${f('Sender name','sender_name')}${ta('Business postal address','physical_address','','required')}</form>`,footer:'<button class="button secondary" data-close-modal>Close</button><button class="button" id="ca-add-connection">Add Connection</button>',onOpen:(root,close)=>$('#ca-add-connection',root).addEventListener('click',async()=>{const form=$('#ca-connect-form',root);if(!form.reportValidity())return;try{await api(`/api/cb1/tenants/${state.selectedTenantId}/providers`,{method:'POST',body:{provider:form.provider.value,sender_email:form.sender_email.value,sender_name:form.sender_name.value,physical_address:form.physical_address.value,config:{},credentials:{}}});toast('Mailbox connection created');close();ctx.navigate('email')}catch(e){toast(e.message,'error')}})});}
function bindEmailActions(ctx){$$('[data-connection-action]').forEach(btn=>btn.addEventListener('click',async()=>{if(btn.dataset.connectionAction==='disconnect'&&!confirm('Disconnect this client mailbox?'))return;try{const result=await api(`/api/v521/tenants/${state.selectedTenantId}/email-connections/${btn.dataset.connectionId}/action`,{method:'POST',body:{action:btn.dataset.connectionAction}});toast(result.detail);ctx.navigate('email')}catch(e){toast(e.message,'error')}}));$$('[data-message-detail]').forEach(btn=>btn.addEventListener('click',()=>messageDetailModal(btn.dataset.messageDetail)))}
async function messageDetailModal(id){try{const data=await api(`/api/v522/tenants/${state.selectedTenantId}/messages/${id}`);const m=data.message,d=data.delivery||{},a=data.actor||{},r=data.relationship||{};modal({title:'Sent message detail',wide:true,body:`<div class="message-detail-grid"><div><span>From</span><strong>${esc(d.sender_name||'')} ${d.sender_email?`&lt;${esc(d.sender_email)}&gt;`:''}</strong></div><div><span>To</span><strong>${esc(d.recipient_name||'')} ${m.recipient_email?`&lt;${esc(m.recipient_email)}&gt;`:''}</strong></div><div><span>Subject</span><strong>${esc(m.subject)}</strong></div><div><span>Status</span><strong>${esc(d.delivery_status||m.status)}</strong></div><div><span>Mailbox / Provider</span><strong>${esc(d.provider||'unknown')}</strong></div><div><span>Sent by</span><strong>${esc(a.name||m.actor_name||'Unknown')} ${a.email?`(${esc(a.email)})`:''}</strong></div><div><span>Sent</span><strong>${dt(m.sent_at||m.created_at)}</strong></div><div><span>CRM relationship</span><strong>${esc(r.type||'None')} ${r.label?`— ${esc(r.label)}`:''}</strong></div><div><span>Provider message ID</span><strong>${esc(m.provider_message_id||'Not available')}</strong></div><div><span>Record type</span><strong>${esc(data.provenance||'One-to-one communication')}</strong></div></div><h3>Message body</h3><div class="message-body">${esc(m.body||'')}</div>`,footer:'<button class="button" data-close-modal>Done</button>'})}catch(e){toast(e.message,'error')}}

async function forecast(page,ctx){
  const [data,provenance]=await Promise.all([api(`/api/tenants/${state.selectedTenantId}/forecast`),api(`/api/v521/tenants/${state.selectedTenantId}/forecast-provenance`)]);if(!data.version){page.innerHTML=`${pageHead('Sales Forecasting','Create an operating forecast to begin.')}<div class="ca-empty">No active forecast version.</div>`;return}
  const months=Array.from({length:12},(_,i)=>i+1),names=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];const rowsBy={};data.months.forEach(m=>(rowsBy[m.account_id]??={})[m.month]=m);
  page.innerHTML=`${pageHead('Sales Forecasting','Forecast by account and month with transparent source data, currency formatting and file-based import.',`<button class="button" id="ca-upload-forecast">Upload CSV/XLSX</button><a class="button secondary" href="/api/v521/tenants/${state.selectedTenantId}/forecast-import/template">Download Template</a>`)}<div class="ca-source-grid"><div class="ca-source-card"><span>Prior Year</span><strong>Imported historical actuals</strong></div><div class="ca-source-card"><span>Operating Forecast</span><strong>Client-entered forecast</strong></div><div class="ca-source-card"><span>Actual to Date</span><strong>${currency(provenance.actual_to_date_cents)}</strong><small>${esc(provenance.actual_source)}</small></div><div class="ca-source-card"><span>CRM Closed Won</span><strong>${currency(provenance.closed_won_revenue_cents)}</strong><small>${esc(provenance.closed_won_source)}</small></div></div><div class="ca-layout-help">Account names remain fixed while you scroll horizontally. Money values display as currency and save back to the active forecast.</div><div class="ca-table-wrap"><table class="ca-table"><thead><tr><th class="sticky-1">Account</th>${names.map(x=>`<th>${x}</th>`).join('')}<th>Total</th></tr></thead><tbody>${data.accounts.map(a=>`<tr><td class="sticky-1"><strong>${esc(a.name)}</strong><small style="display:block;color:#68788e">${esc(a.status)}</small></td>${months.map(month=>{const row=rowsBy[a.id]?.[month];return `<td>${row?`<input class="ca-money-input" data-forecast-id="${row.id}" value="${(row.forecast_cents/100).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})}">`:'—'}</td>`}).join('')}<td><strong>${currency(months.reduce((sum,m)=>sum+(rowsBy[a.id]?.[m]?.forecast_cents||0),0))}</strong></td></tr>`).join('')}</tbody></table></div>`;
  $$('.ca-money-input').forEach(input=>input.addEventListener('change',async()=>{const raw=input.value.replace(/[$,]/g,'');const dollars=Number(raw);if(!Number.isFinite(dollars)){toast('Enter a valid money amount','error');return}try{await api(`/api/forecast/months/${input.dataset.forecastId}`,{method:'PATCH',body:{forecast_cents:Math.round(dollars*100)}});input.value=dollars.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});toast('Forecast updated')}catch(e){toast(e.message,'error')}}));$('#ca-upload-forecast').addEventListener('click',()=>forecastImportModal(data.version,ctx));
}
function forecastImportModal(version,ctx){modal({title:'Upload prior-year, actual or forecast sales',wide:true,body:`<div class="ca-dialog-note">Upload a CSV or XLSX file with columns: Account, Month, Amount, Target. Target may be prior_actual, actual or forecast. Currency symbols and comma separators are normalized.</div><form id="ca-forecast-upload" class="ca-form"><div class="ca-file-drop"><input type="file" name="file" accept=".csv,.xlsx,.xlsm" required></div></form><div id="ca-import-preview"></div>`,footer:'<button class="button secondary" data-close-modal>Cancel</button><button class="button" id="ca-preview-import">Preview & Validate</button><button class="button ca-hidden" id="ca-commit-import">Import Valid Rows</button>',onOpen:(root,close)=>{let batch=null;$('#ca-preview-import',root).addEventListener('click',async()=>{const file=$('#ca-forecast-upload',root).file.files[0];if(!file){toast('Choose a CSV or XLSX file','error');return}const fd=new FormData();fd.append('version_id',version.id);fd.append('file',file);try{const result=await api(`/api/v521/tenants/${state.selectedTenantId}/forecast-import/preview`,{method:'POST',body:fd});batch=result.batch;$('#ca-import-preview',root).innerHTML=`<div class="ca-confirm">${result.rows.length} valid row(s); ${result.exceptions.length} exception(s).</div><div class="ca-table-wrap"><table class="ca-table"><thead><tr><th>Account</th><th>Month</th><th>Amount</th><th>Target</th></tr></thead><tbody>${result.rows.map(x=>`<tr><td>${esc(x.account)}</td><td>${x.month}</td><td>${esc(x.display_amount)}</td><td>${esc(x.target)}</td></tr>`).join('')}</tbody></table></div>${result.exceptions.length?`<div class="ca-error">${result.exceptions.map(x=>`Row ${x.row}: ${esc(x.reason)}`).join('<br>')}</div>`:''}`;$('#ca-commit-import',root).classList.toggle('ca-hidden',!result.ready_to_import)}catch(e){toast(e.message,'error')}});$('#ca-commit-import',root).addEventListener('click',async()=>{if(!batch)return;try{const result=await api(`/api/v521/tenants/${state.selectedTenantId}/forecast-import/commit`,{method:'POST',body:{batch_id:batch.id}});toast(`Imported ${result.changed_rows.length} row(s)`);close();ctx.navigate('forecast')}catch(e){toast(e.message,'error')}})}});}

async function reports(page,ctx){const data=await api(`/api/v521/tenants/${state.selectedTenantId}/action-report`);page.innerHTML=`${pageHead('Growth & Management Reporting','Understand performance, open the underlying records, and act on what needs attention.')}<section class="ca-section"><div class="ca-section-head"><div><h2>What Needs My Attention?</h2><p>Prioritized actions from the current tenant data.</p></div></div><div class="ca-attention">${data.attention.map(x=>`<div class="ca-attention-item"><div><strong>${esc(x.title)}</strong><small style="display:block">${esc(x.detail)}</small></div><button class="button small" data-report-route="${esc(x.route)}">${esc(x.label)}</button></div>`).join('')||'<div class="ca-confirm">No urgent actions were identified.</div>'}</div></section><div class="ca-action-grid">${data.kpis.map(x=>`<button class="ca-action-card" data-report-route="${esc(x.route)}"><span>${esc(x.label)}</span><strong>${x.value_cents!==undefined?currency(x.value_cents):number(x.value)}</strong><span>Open details →</span></button>`).join('')}</div><div class="ca-grid-2"><section class="ca-section"><h2>Growth Funnel</h2><div class="ca-list">${data.funnel.map(x=>`<button class="ca-list-row ca-clickable" data-report-route="${esc(x.route)}"><span>${esc(x.label)}</span><strong>${number(x.value)}</strong></button>`).join('')}</div></section><section class="ca-section"><h2>Source Attribution</h2><div class="ca-list">${data.sources.map(x=>`<button class="ca-list-row ca-clickable" data-report-route="${esc(x.route)}"><span>${esc(x.source)}<small>${number(x.opportunities)} opportunity(s)</small></span><strong>${currency(x.value_cents)}</strong></button>`).join('')||'<div class="ca-empty">No opportunity sources yet.</div>'}</div></section></div>`;$$('[data-report-route]').forEach(btn=>btn.addEventListener('click',()=>openReportRoute(btn.dataset.reportRoute,ctx)))}
function openReportRoute(route,ctx){const [name,query='']=route.split('?');const params=new URLSearchParams(query);if(name==='crm'&&params.get('tab'))state.crmTab=params.get('tab');ctx.navigate(name)}

async function training(page,ctx){const data=await api(`/api/v521/tenants/${state.selectedTenantId}/client-training`);page.innerHTML=`${pageHead('Client Training Library','Upload or link training that teaches staff how your company expects RMR Global to be used.',`<button class="button" id="ca-add-training">+ Add Training</button>`)}<div class="ca-notice"><div><strong>Client workflow training now; RMR platform training later</strong><small>Clients create training for their own sales process and desired workflow. RMR can add actual product-support videos after the product is stable.</small></div></div><div class="ca-grid-3">${data.resources.map(r=>`<article class="ca-training-card"><div class="ca-status-row"><span class="ca-pill">${esc(r.category)}</span><span class="ca-pill ${r.required?'amber':''}">${r.required?'Required':'Optional'}</span><span class="ca-pill">${esc(r.owner_scope)}</span></div><h3>${esc(r.title)}</h3><p>${esc(r.description)}</p>${r.media_type==='uploaded_video'?`<video controls src="/api/v521/client-training/${r.id}/media"></video>`:`<a class="button secondary small" href="${esc(r.media_url)}" target="_blank">Open Video</a>`}<div class="ca-list" style="margin-top:10px">${r.assignments.map(a=>`<div class="ca-list-row"><div><strong>${esc(a.user_name)}</strong><small>${esc(a.status)} · ${a.progress_pct}%</small></div><button class="button secondary small" data-training-complete="${a.id}">${a.status==='complete'?'Completed':'Mark Complete'}</button></div>`).join('')||'<small>No individual assignments.</small>'}</div>${r.owner_scope==='client'?`<button class="button secondary small" data-archive-training="${r.id}" style="margin-top:10px">Archive</button>`:''}</article>`).join('')||'<div class="ca-empty">No client training yet. Add the first workflow video.</div>'}</div>`;$('#ca-add-training').addEventListener('click',()=>trainingModal(data.users,ctx));$$('[data-training-complete]').forEach(btn=>btn.addEventListener('click',async()=>{try{await api(`/api/v521/client-training/assignments/${btn.dataset.trainingComplete}`,{method:'PATCH',body:{status:'complete',progress_pct:100}});toast('Training completed');ctx.navigate('training')}catch(e){toast(e.message,'error')}}));$$('[data-archive-training]').forEach(btn=>btn.addEventListener('click',async()=>{if(!confirm('Archive this training resource?'))return;try{await api(`/api/v521/client-training/${btn.dataset.archiveTraining}`,{method:'DELETE',body:{}});toast('Training archived');ctx.navigate('training')}catch(e){toast(e.message,'error')}}))}
function trainingModal(users,ctx){const roles=[['CLIENT_ADMIN','Client Administrator'],['VP_SALES','VP of Sales'],['SALES_MANAGER','Sales Manager'],['SALES_REP','Sales Representative'],['MARKETING_USER','Marketing User'],['EXECUTIVE_VIEWER','Executive Viewer']];modal({title:'Add client workflow training',wide:true,body:`<form id="ca-training-form" class="ca-form ca-modal-grid" enctype="multipart/form-data">${f('Title','title','text','','required')}${f('Category','category','text','Sales Workflow')}${ta('Description','description')}${f('Hosted video URL (optional)','media_url','url')}${f('Upload video (optional)','file','file','','accept=".mp4,.webm,.mov,.m4v"')}${sel('Required or optional','required',[['false','Optional'],['true','Required']],'false')}${f('Due date (optional)','due_date','date')}<div class="field full"><label>Assign by role</label>${roles.map(([v,l])=>`<label><input type="checkbox" name="role" value="${v}"> ${l}</label>`).join(' ')}</div><div class="field full"><label>Assign specific users (optional)</label>${users.map(u=>`<label><input type="checkbox" name="user_id" value="${u.id}"> ${esc(u.name)}</label>`).join(' ')}</div></form>`,footer:'<button class="button secondary" data-close-modal>Cancel</button><button class="button" id="ca-save-training">Save Training</button>',onOpen:(root,close)=>$('#ca-save-training',root).addEventListener('click',async()=>{const form=$('#ca-training-form',root);if(!form.reportValidity())return;const fd=new FormData();['title','category','description','media_url','due_date'].forEach(k=>fd.append(k,form[k].value));fd.append('required',form.required.value);fd.append('roles_json',JSON.stringify($$('input[name=role]:checked',form).map(x=>x.value)));fd.append('user_ids_json',JSON.stringify($$('input[name=user_id]:checked',form).map(x=>x.value)));if(form.file.files[0])fd.append('file',form.file.files[0]);try{await api(`/api/v521/tenants/${state.selectedTenantId}/client-training`,{method:'POST',body:fd});toast('Training added');close();ctx.navigate('training')}catch(e){toast(e.message,'error')}})});}

async function organization(page,ctx){const data=await api(`/api/tenants/${state.selectedTenantId}/sales-organization`);const byId=Object.fromEntries(data.people.map(p=>[p.id,p]));page.innerHTML=`${pageHead('Team & Sales Organization','Manage roles, reporting relationships, team assignments and secure account access.',`<button class="button" id="ca-invite-user">+ Invite Team Member</button>`)}<section class="ca-section"><div class="ca-table-wrap"><table class="ca-table"><thead><tr><th>Team Member</th><th>Role</th><th>Team</th><th>Reports To</th><th>Accounts</th><th>Status</th><th>Actions</th></tr></thead><tbody>${data.people.map(p=>`<tr><td><strong>${esc(p.full_name)}</strong><small style="display:block">${esc(p.email)}</small></td><td>${esc(roleLabel(p.tenant_role))}</td><td>${esc(p.team_name||'—')}</td><td>${esc(byId[p.manager_id]?.full_name||'—')}</td><td>${number(p.account_count)}</td><td><span class="ca-pill ${p.active?'green':''}">${p.active?'Active':'Inactive'}</span></td><td><div class="ca-toolbar"><button class="button secondary small" data-team-edit="${p.id}">Edit</button><button class="button secondary small" data-team-reset="${p.id}">Send Password Reset</button><button class="button secondary small" data-team-toggle="${p.id}" data-active="${p.active}">${p.active?'Deactivate':'Activate'}</button></div></td></tr>`).join('')}</tbody></table></div></section>`;$('#ca-invite-user').addEventListener('click',()=>inviteTeamMember(data.people,ctx));$$('[data-team-edit]').forEach(btn=>btn.addEventListener('click',()=>editTeamMember(data.people.find(p=>p.id===btn.dataset.teamEdit),data.people,ctx)));$$('[data-team-reset]').forEach(btn=>btn.addEventListener('click',async()=>{try{const result=await api(`/api/v521/tenants/${state.selectedTenantId}/users/send-password-reset`,{method:'POST',body:{user_id:btn.dataset.teamReset}});if(result.delivery==='local_recovery')showLocalReset(result);else toast(`Password reset sent to ${result.email}`)}catch(e){toast(e.message,'error')}}));$$('[data-team-toggle]').forEach(btn=>btn.addEventListener('click',async()=>{try{await api(`/api/tenant-users/${btn.dataset.teamToggle}`,{method:'PATCH',body:{active:btn.dataset.active!=='true'}});toast(btn.dataset.active==='true'?'User deactivated':'User activated');ctx.navigate('organization')}catch(e){toast(e.message,'error')}}))}
function showLocalReset(result){modal({title:'Local Product Owner reset link',body:`<div class="ca-notice warn"><div><strong>Authorized fallback only</strong><small>Production uses system transactional email. This local link exists only because the Product Owner environment has no configured transactional email provider.</small></div></div><div class="secure-link"><code>${esc(result.local_reset_url)}</code><a class="button secondary small" href="${esc(result.local_reset_url)}" target="_blank">Open</a></div><p>Expires: ${esc(result.expires_at)}</p>`,footer:'<button class="button" data-close-modal>Done</button>'})}
function inviteTeamMember(people,ctx){const roles=[['CLIENT_ADMIN','Client Administrator'],['VP_SALES','VP of Sales'],['SALES_MANAGER','Sales Manager'],['SALES_REP','Sales Representative'],['MARKETING_USER','Marketing User'],['EXECUTIVE_VIEWER','Executive Viewer']];modal({title:'Invite team member',body:`<form id="ca-invite-form" class="ca-form ca-modal-grid">${f('Full name','full_name','text','','required')}${f('Email','email','email','','required')}${sel('Role','tenant_role',roles,'SALES_REP')}${sel('Reports to','manager_id',[['','No manager'],...people.map(p=>[p.id,p.full_name])])}${f('Team or region','team_name')}</form>`,footer:'<button class="button secondary" data-close-modal>Cancel</button><button class="button" id="ca-send-invite">Create Invitation</button>',onOpen:(root,close)=>$('#ca-send-invite',root).addEventListener('click',async()=>{const form=$('#ca-invite-form',root);if(!form.reportValidity())return;try{const result=await api(`/api/tenants/${state.selectedTenantId}/users`,{method:'POST',body:{full_name:form.full_name.value,email:form.email.value,tenant_role:form.tenant_role.value,manager_id:form.manager_id.value||null,team_name:form.team_name.value}});toast('Invitation created');close();if(result.activation_url)modal({title:'Local activation link',body:`<div class="secure-link"><code>${esc(result.activation_url)}</code><a class="button secondary small" href="${esc(result.activation_url)}" target="_blank">Open</a></div>`,footer:'<button class="button" data-close-modal>Done</button>'});else ctx.navigate('organization')}catch(e){toast(e.message,'error')}})});}
function editTeamMember(person,people,ctx){const roles=[['CLIENT_ADMIN','Client Administrator'],['VP_SALES','VP of Sales'],['SALES_MANAGER','Sales Manager'],['SALES_REP','Sales Representative'],['MARKETING_USER','Marketing User'],['EXECUTIVE_VIEWER','Executive Viewer']];modal({title:'Edit team member',body:`<form id="ca-edit-person" class="ca-form ca-modal-grid">${f('Full name','full_name','text',person.full_name,'required')}${f('Email','email','email',person.email,'required')}${sel('Role','tenant_role',roles,person.tenant_role)}${sel('Reports to','manager_id',[['','No manager'],...people.filter(p=>p.id!==person.id).map(p=>[p.id,p.full_name])],person.manager_id||'')}${f('Team or region','team_name','text',person.team_name||'')}</form>`,footer:'<button class="button secondary" data-close-modal>Cancel</button><button class="button" id="ca-save-person">Save</button>',onOpen:(root,close)=>$('#ca-save-person',root).addEventListener('click',async()=>{const form=$('#ca-edit-person',root);if(!form.reportValidity())return;try{await api(`/api/tenant-users/${person.id}`,{method:'PATCH',body:{full_name:form.full_name.value,email:form.email.value,tenant_role:form.tenant_role.value,manager_id:form.manager_id.value||null,team_name:form.team_name.value,active:person.active}});toast('Team member updated');close();ctx.navigate('organization')}catch(e){toast(e.message,'error')}})});}

async function solutions(page,ctx){const [data,requests]=await Promise.all([api(`/api/tenants/${state.selectedTenantId}/solutions`),api(`/api/v521/tenants/${state.selectedTenantId}/solution-request-status`)]);const reqBy=Object.fromEntries(requests.items.filter(x=>['Requested','Pending Activation'].includes(x.status)).map(x=>[x.service_code,x]));const active=data.solutions.filter(x=>x.status==='Active'),available=data.solutions.filter(x=>x.status!=='Active');page.innerHTML=`${pageHead('Solutions Center','See current subscriptions and client pricing, explore additional solutions, and request a conversation without automatic activation or billing.')}<div class="ca-notice"><div><strong>Requests do not activate services or create charges</strong><small>RMR confirms scope, pricing and the requested contact time before any solution is activated.</small></div></div><section class="ca-section"><div class="ca-section-head"><div><h2>Active Services</h2><p>Current subscriptions and client pricing.</p></div></div><div class="ca-grid-3">${active.map(solutionCard).join('')||'<div class="ca-empty">No active services.</div>'}</div></section><section class="ca-section"><div class="ca-section-head"><div><h2>Available Solutions</h2><p>Explore and request additional services.</p></div></div><div class="ca-grid-3">${available.map(x=>solutionCard(x,reqBy[x.service.code],ctx)).join('')||'<div class="ca-empty">No additional solutions available.</div>'}</div></section>`;$$('[data-request-solution]').forEach(btn=>btn.addEventListener('click',()=>solutionRequestModal(btn.dataset.requestSolution,btn.dataset.solutionName,ctx)))}
function solutionCard(x,request){const price=x.tenant_service?.contract_price_cents??x.service.standard_price_cents;const active=x.status==='Active';return `<article class="ca-request-card ${active?'active':''}"><div class="ca-status-row"><span class="ca-pill ${active?'green':'amber'}">${active?'Active':request?'Request Submitted':'Available'}</span></div><h3>${esc(x.service.name)}</h3><p>${esc(x.service.description||'')}</p><strong>${currency(price)} ${esc(x.service.cadence||'monthly')}</strong>${active?'<p class="ca-requirement">Currently subscribed.</p>':request?`<p class="ca-requirement">Status: ${esc(request.status)}${request.preference?` · Requested ${esc(request.preference.contact_date)} ${esc(request.preference.contact_time)} ${esc(request.preference.timezone)}`:''}</p>`:`<button class="button small" data-request-solution="${x.service.code}" data-solution-name="${esc(x.service.name)}">Request This Solution</button>`}</article>`}
function solutionRequestModal(code,name,ctx){const tenant=state.tenants.find(t=>t.id===state.selectedTenantId);modal({title:`Request ${name}`,body:`<div class="ca-dialog-note">Tell RMR what you would like to accomplish. The date/time below is a requested contact window, not a confirmed appointment.</div><form id="ca-solution-form" class="ca-form ca-modal-grid">${ta('What would you like help accomplishing?','note','','required')}${sel('Preferred contact method','preferred_contact_method',[['Email','Email'],['Phone','Phone'],['Video Meeting','Video Meeting']],'Email')}${f('Preferred contact date','contact_date','date','','required')}${f('Preferred contact time','contact_time','time','','required')}${f('Timezone','timezone','text',tenant?.timezone||Intl.DateTimeFormat().resolvedOptions().timeZone,'required')}</form>`,footer:'<button class="button secondary" data-close-modal>Cancel</button><button class="button" id="ca-submit-solution">Submit Request</button>',onOpen:(root,close)=>$('#ca-submit-solution',root).addEventListener('click',async()=>{const form=$('#ca-solution-form',root);if(!form.reportValidity())return;try{const result=await api(`/api/v521/tenants/${state.selectedTenantId}/solution-requests`,{method:'POST',body:{service_code:code,note:form.note.value,preferred_contact_method:form.preferred_contact_method.value,contact_date:form.contact_date.value,contact_time:form.contact_time.value,timezone:form.timezone.value}});toast(result.confirmation||'Request received');close();ctx.navigate('solutions')}catch(e){toast(e.message,'error')}})});}
